-- Только права и schema metadata; имена LOGIN, credentials и строки контекста не выдаются.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout = '5s';
SET LOCAL lock_timeout = '500ms';
SET LOCAL search_path=pg_catalog;
DO $personal_catalog$
DECLARE v_actual jsonb;
BEGIN
-- name: personal_credentials_catalog :one
-- Только schema metadata синтетического либо явно выбранного control-plane schema.
-- Business rows, LOGIN identities, credential descriptors и значения не читаются.
WITH RECURSIVE relations AS (
  SELECT c.* FROM pg_catalog.pg_class c
  WHERE c.relnamespace='control_plane'::regnamespace AND c.relkind IN ('r','p')
    AND (c.relname LIKE 'integration_personal_%' OR c.relname IN
      ('integration_connections','integration_invocations','runs'))
), functions AS (
  SELECT p.* FROM pg_catalog.pg_proc p
  WHERE p.pronamespace='control_plane'::regnamespace AND
    (p.proname LIKE 'guard_personal_%' OR p.proname IN
      ('cancel_personal_tests_on_connection_change','integration_connection_configuration_ready','integration_grant_admission','purge_project_database')
     OR p.oid IN (SELECT t.tgfoid FROM pg_catalog.pg_trigger t JOIN relations r ON r.oid=t.tgrelid WHERE NOT t.tgisinternal))
), purge_nodes(id) AS (
  SELECT 'control_plane.projects'::regclass::oid UNION
  SELECT c.conrelid FROM purge_nodes n JOIN pg_catalog.pg_constraint c ON c.confrelid=n.id
  WHERE c.contype='f' AND c.connamespace='control_plane'::regnamespace
), predecessor_purge_nodes AS (
  SELECT id FROM purge_nodes WHERE id NOT IN
    ('control_plane.integration_personal_invocation_credentials'::regclass,
     'control_plane.integration_personal_invocation_admissions'::regclass)
), purge_node_metadata AS (
  SELECT r.oid AS id,n.nspname||'.'||r.relname AS name
  FROM purge_nodes selected JOIN pg_catalog.pg_class r ON r.oid=selected.id
  JOIN pg_catalog.pg_namespace n ON n.oid=r.relnamespace
), purge_edge_metadata AS (
  SELECT c.conrelid AS child_id,c.confrelid AS parent_id,cn.nspname||'.'||child.relname AS child,
    c.conname,pn.nspname||'.'||parent.relname AS parent,c.confdeltype::text AS deletion,
    cn.nspname||'.'||child.relname||'|'||c.conname||'|'||pn.nspname||'.'||parent.relname||'|'||c.confdeltype::text AS pin,
    jsonb_build_array(cn.nspname||'.'||child.relname,c.conname,pn.nspname||'.'||parent.relname,
      c.confdeltype,c.confupdtype,c.confmatchtype,c.condeferrable,c.condeferred,c.convalidated,c.conenforced,
      c.conislocal,c.coninhcount,pg_get_constraintdef(c.oid)) AS metadata
  FROM pg_catalog.pg_constraint c JOIN pg_catalog.pg_class child ON child.oid=c.conrelid
  JOIN pg_catalog.pg_namespace cn ON cn.oid=child.relnamespace
  JOIN pg_catalog.pg_class parent ON parent.oid=c.confrelid
  JOIN pg_catalog.pg_namespace pn ON pn.oid=parent.relnamespace
  WHERE c.contype='f' AND c.conrelid IN (SELECT id FROM purge_nodes)
    AND c.confrelid IN (SELECT id FROM purge_nodes)
), table_catalog AS (
  SELECT r.relname,jsonb_build_object(
    'kind',r.relkind,'persistence',r.relpersistence,'owner',pg_get_userbyid(r.relowner),
    'rls',r.relrowsecurity,'forceRls',r.relforcerowsecurity,'replicaIdentity',r.relreplident,
    'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,
      a.atthasdef,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated,a.attacl::text) ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
      WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
    'constraints',(SELECT jsonb_object_agg(c.conname,jsonb_build_array(c.contype,c.convalidated,c.conenforced,
      c.condeferrable,c.condeferred,c.conislocal,c.coninhcount,c.connoinherit,pg_get_constraintdef(c.oid)))
      FROM pg_catalog.pg_constraint c WHERE c.conrelid=r.oid),
    'indexes',(SELECT jsonb_object_agg(i.indexrelid::regclass::text,jsonb_build_array(i.indisunique,i.indisvalid,
      i.indisready,i.indislive,pg_get_indexdef(i.indexrelid))) FROM pg_catalog.pg_index i WHERE i.indrelid=r.oid),
    'policies',(SELECT jsonb_object_agg(p.polname,jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,
      'roles',(SELECT jsonb_agg(CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_id) END ORDER BY role_id=0,pg_get_userbyid(role_id)) FROM unnest(p.polroles) role_id),
      'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)))
      FROM pg_catalog.pg_policy p WHERE p.polrelid=r.oid),
    'parents',(SELECT jsonb_agg(i.inhparent::regclass::text ORDER BY i.inhparent::regclass::text) FROM pg_catalog.pg_inherits i WHERE i.inhrelid=r.oid),
    'children',(SELECT jsonb_agg(i.inhrelid::regclass::text ORDER BY i.inhrelid::regclass::text) FROM pg_catalog.pg_inherits i WHERE i.inhparent=r.oid),
    'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type)
      FROM aclexplode(coalesce(r.relacl,acldefault('r',r.relowner))) a)
  ) AS metadata FROM relations r
), function_catalog AS (
  SELECT p.oid::regprocedure::text AS name,jsonb_build_object(
    'definition',pg_get_functiondef(p.oid),'sourceMD5',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
    'definer',p.prosecdef,'kind',p.prokind,'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,
    'leakproof',p.proleakproof,'set',p.proretset,'result',pg_get_function_result(p.oid),
    'argumentNames',p.proargnames,'argumentModes',p.proargmodes,'argumentTypes',pg_get_function_identity_arguments(p.oid),
    'defaults',p.pronargdefaults,'configuration',p.proconfig,
    'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type)
      FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)
  ) AS metadata FROM functions p JOIN pg_catalog.pg_language l ON l.oid=p.prolang
), trigger_catalog AS (
  SELECT r.relname||'.'||t.tgname AS name,jsonb_build_array(pg_get_triggerdef(t.oid),t.tgtype,t.tgenabled,
    t.tgdeferrable,t.tginitdeferred,t.tgconstraint<>0,encode(t.tgargs,'hex')) AS metadata
  FROM relations r JOIN pg_catalog.pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal
)
SELECT jsonb_build_object(
 'tables',(SELECT jsonb_object_agg(relname,metadata) FROM table_catalog),
 'functions',(SELECT jsonb_object_agg(name,metadata) FROM function_catalog),
 'triggers',(SELECT jsonb_object_agg(name,metadata) FROM trigger_catalog),
 'purgeGraph',jsonb_build_object(
   'nodes',(SELECT jsonb_agg(name ORDER BY name) FROM purge_node_metadata),
   'edges',(SELECT jsonb_agg(metadata ORDER BY child,conname) FROM purge_edge_metadata),
   'nodeCount',(SELECT count(*) FROM purge_nodes),
   'edgeCount',(SELECT count(*) FROM purge_edge_metadata),
   'nodeFingerprint',(SELECT md5(string_agg(name,E'\n' ORDER BY name)) FROM purge_node_metadata),
   'edgeFingerprint',(SELECT md5(string_agg(pin,E'\n' ORDER BY child,conname)) FROM purge_edge_metadata),
   'predecessorNodeCount',(SELECT count(*) FROM predecessor_purge_nodes),
   'predecessorEdgeCount',(SELECT count(*) FROM purge_edge_metadata WHERE child_id IN (SELECT id FROM predecessor_purge_nodes) AND parent_id IN (SELECT id FROM predecessor_purge_nodes)),
   'predecessorNodeFingerprint',(SELECT md5(string_agg(name,E'\n' ORDER BY name)) FROM purge_node_metadata WHERE id IN (SELECT id FROM predecessor_purge_nodes)),
   'predecessorEdgeFingerprint',(SELECT md5(string_agg(pin,E'\n' ORDER BY child,conname)) FROM purge_edge_metadata WHERE child_id IN (SELECT id FROM predecessor_purge_nodes) AND parent_id IN (SELECT id FROM predecessor_purge_nodes))),
 'sequences',(SELECT jsonb_agg(c.relname ORDER BY c.relname) FROM pg_catalog.pg_class c
   WHERE c.relnamespace='control_plane'::regnamespace AND c.relkind='S' AND c.relname LIKE 'integration_personal_%')
) INTO v_actual;
IF v_actual IS DISTINCT FROM $expected_personal${"functions":{"control_plane.cancel_personal_tests_on_connection_change()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.cancel_personal_tests_on_connection_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nBEGIN\n    IF NEW.version IS DISTINCT FROM OLD.version THEN\n        UPDATE control_plane.integration_personal_credential_tests\n        SET state='CANCELLED',outcome='CANCELLED',version=version+1,finished_at=clock_timestamp(),\n            lease_ref=NULL,fence_digest=NULL,workload_instance=NULL,lease_expires_at=NULL\n        WHERE connection_id=NEW.id AND state IN ('DUE','CLAIMED','PROBING');\n        UPDATE control_plane.integration_personal_credentials\n        SET state='CHECK_REQUIRED',version=version+1\n        WHERE connection_id=NEW.id AND state='CHECKING';\n        IF (NEW.public_configuration,NEW.definition_version,NEW.definition_digest,NEW.credential_policy)\n           IS DISTINCT FROM (OLD.public_configuration,OLD.definition_version,OLD.definition_digest,OLD.credential_policy) THEN\n            UPDATE control_plane.integration_personal_credentials\n            SET state='CHECK_REQUIRED',version=version+1,verified_credential_revision_id=NULL,\n                verified_definition_digest=NULL,verified_configuration_digest=NULL,\n                verified_capabilities='{}',denied_capabilities='{}',observed_permission_profiles='{}',expires_at=NULL\n            WHERE connection_id=NEW.id AND state IN ('READY','INVALID');\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"eb0baf9151e8ca7dca98d73e7b5d4827","strict":false,"volatility":"v"},"control_plane.close_workspace_volume_origin()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.close_workspace_volume_origin()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE v_task record;\nBEGIN\n -- Родительская owner-команда уже удерживает изменяемую строку origin.\n -- Выборка не расширяется на другие actor/project/session этого organization.\n FOR v_task IN\n   SELECT t.id,t.volume_id,t.volume_generation\n   FROM control_plane.session_workspace_volume_tasks t\n   JOIN control_plane.session_workspace_volumes v ON v.id=t.volume_id\n   JOIN control_plane.session_workspace_storage w ON w.id=v.workspace_id\n   JOIN control_plane.run_nodes n ON n.id=t.origin_node_id\n   WHERE t.state IN('READY','CLAIMED') AND (\n     TG_TABLE_NAME='runs' AND (t.root_run_id=NEW.id OR n.run_id=NEW.id)\n     OR TG_TABLE_NAME='run_nodes' AND t.origin_node_id=NEW.id\n     OR TG_TABLE_NAME='sessions' AND w.session_id=NEW.id\n     OR TG_TABLE_NAME='agents' AND w.agent_id=NEW.id\n     OR TG_TABLE_NAME='projects' AND w.project_id=NEW.id\n     OR TG_TABLE_NAME='subjects' AND t.origin_actor_id=NEW.id)\n   ORDER BY t.root_run_id,w.session_id,v.id,t.id FOR UPDATE OF v,t\n LOOP\n   UPDATE control_plane.session_workspace_volume_attempts SET grant_state='CLOSED'\n   WHERE task_id=v_task.id AND grant_state='ACTIVE';\n   UPDATE control_plane.session_workspace_volume_tasks\n   SET state='CANCELLED',safe_error_code='ORIGIN_CLOSED',completed_at=clock_timestamp(),updated_at=clock_timestamp()\n   WHERE id=v_task.id AND state IN('READY','CLAIMED');\n   UPDATE control_plane.session_workspace_volumes\n   SET state='BLOCKED',block_reason='ORIGIN_CLOSED',version=version+1,updated_at=clock_timestamp()\n   WHERE id=v_task.volume_id AND generation=v_task.volume_generation AND state NOT IN('READY','PURGED');\n END LOOP;\n RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"81c19e4d9305a95faa68f1f256f8668a","strict":false,"volatility":"v"},"control_plane.guard_legacy_workflow_rework()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_legacy_workflow_rework()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nDECLARE original record; first_node record;\nBEGIN\n    IF TG_TABLE_NAME='runs' THEN\n        IF EXISTS (SELECT 1 FROM control_plane.run_nodes node WHERE node.run_id=OLD.id\n            AND node.organization_id=OLD.organization_id AND node.owner_rework_gate_id IS NOT NULL) THEN\n            IF TG_OP='DELETE' THEN\n                IF NOT control_plane.project_purge_authorized() OR NOT EXISTS (\n                    SELECT 1 FROM control_plane.project_purge_targets target\n                    JOIN control_plane.project_purge_context context USING (transaction_id)\n                    WHERE target.transaction_id=pg_current_xact_id_if_assigned() AND context.backend_pid=pg_backend_pid()\n                        AND target.relation_id='control_plane.runs'::regclass AND target.row_key=jsonb_build_array(OLD.id)\n                ) THEN RAISE EXCEPTION 'legacy rework run requires exact project purge' USING ERRCODE='23514'; END IF;\n            ELSIF ROW(NEW.id,NEW.ref,NEW.organization_id,NEW.project_id,NEW.session_id,NEW.root_run_id,NEW.parent_run_id,\n                NEW.workflow_version_id,NEW.retry_of_run_id,NEW.target_type,NEW.target_ref,NEW.source,NEW.attempt,NEW.initiated_by,\n                NEW.task,NEW.input,NEW.created_at,NEW.started_at) IS DISTINCT FROM ROW(\n                OLD.id,OLD.ref,OLD.organization_id,OLD.project_id,OLD.session_id,OLD.root_run_id,OLD.parent_run_id,\n                OLD.workflow_version_id,OLD.retry_of_run_id,OLD.target_type,OLD.target_ref,OLD.source,OLD.attempt,OLD.initiated_by,\n                OLD.task,OLD.input,OLD.created_at,OLD.started_at) THEN\n                RAISE EXCEPTION 'legacy rework physical run lineage is immutable' USING ERRCODE='23514';\n            END IF;\n        END IF;\n        IF TG_OP='DELETE' THEN RETURN OLD; END IF;\n        RETURN NEW;\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.owner_rework_gate_id IS NOT NULL THEN\n            IF NOT control_plane.project_purge_authorized() OR NOT EXISTS (\n                SELECT 1 FROM control_plane.project_purge_targets target\n                JOIN control_plane.project_purge_context context USING (transaction_id)\n                WHERE target.transaction_id=pg_current_xact_id_if_assigned() AND context.backend_pid=pg_backend_pid()\n                    AND target.relation_id='control_plane.run_nodes'::regclass AND target.row_key=jsonb_build_array(OLD.id)\n            ) THEN RAISE EXCEPTION 'legacy rework requires exact authorized project purge' USING ERRCODE='23514'; END IF;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF TG_OP='UPDATE' AND OLD.owner_rework_gate_id IS NOT NULL AND ROW(\n        NEW.id,NEW.ref,NEW.organization_id,NEW.root_run_id,NEW.run_id,NEW.parent_node_id,NEW.agent_id,\n        NEW.turn_id,NEW.workflow_step_key,NEW.attempt,NEW.owner_rework_gate_id,NEW.owner_rework_origin_node_id,NEW.human_gate_after\n    ) IS DISTINCT FROM ROW(\n        OLD.id,OLD.ref,OLD.organization_id,OLD.root_run_id,OLD.run_id,OLD.parent_node_id,OLD.agent_id,\n        OLD.turn_id,OLD.workflow_step_key,OLD.attempt,OLD.owner_rework_gate_id,OLD.owner_rework_origin_node_id,OLD.human_gate_after\n    ) THEN RAISE EXCEPTION 'legacy rework assignment is immutable' USING ERRCODE='23514'; END IF;\n    IF TG_OP='UPDATE' AND OLD.owner_rework_gate_id IS NULL AND NEW.owner_rework_gate_id IS NOT NULL THEN\n        RAISE EXCEPTION 'legacy rework cannot reinterpret an existing node' USING ERRCODE='23514';\n    END IF;\n    IF NEW.owner_rework_gate_id IS NULL THEN RETURN NEW; END IF;\n    IF NEW.workflow_business_attempt<>0 OR NEW.workflow_step_origin_node_id IS NOT NULL\n       OR NEW.type<>'AGENT_EXECUTION' OR NEW.materialization_state<>'MATERIALIZED' OR NOT NEW.human_gate_after THEN\n        RAISE EXCEPTION 'legacy rework cannot impersonate SERVER provenance' USING ERRCODE='23514';\n    END IF;\n    SELECT predecessor.id AS node_id,predecessor.run_id,logical_origin.workflow_step_key,\n           predecessor.agent_id,prior.attempt AS run_attempt,prior.project_id,prior.initiated_by,\n           root.id AS root_id,root.workflow_version_id\n    INTO original\n    FROM control_plane.owner_gates gate\n    JOIN control_plane.run_nodes gate_node ON gate_node.id=gate.node_id AND gate_node.organization_id=gate.organization_id\n        AND gate_node.root_run_id=gate.root_run_id AND gate_node.type='HUMAN_GATE'\n    JOIN control_plane.run_nodes predecessor ON predecessor.id=gate_node.parent_node_id\n        AND predecessor.organization_id=gate.organization_id AND predecessor.root_run_id=gate.root_run_id\n    JOIN LATERAL control_plane.legacy_workflow_step_origin(NEW.organization_id,predecessor.id) AS origin_id(id) ON true\n    JOIN control_plane.run_nodes logical_origin ON logical_origin.id=origin_id.id AND logical_origin.organization_id=NEW.organization_id\n    JOIN control_plane.runs prior ON prior.id=predecessor.run_id AND prior.organization_id=gate.organization_id\n    JOIN control_plane.runs root ON root.id=gate.root_run_id AND root.organization_id=gate.organization_id\n        AND root.project_id=gate.project_id AND root.project_id=prior.project_id AND root.id<>prior.id\n    JOIN control_plane.workflow_versions version ON version.id=root.workflow_version_id AND version.organization_id=root.organization_id\n    JOIN control_plane.workflows workflow ON workflow.id=version.workflow_id AND workflow.organization_id=root.organization_id\n        AND workflow.project_id=root.project_id\n    JOIN control_plane.agents agent ON agent.id=predecessor.agent_id AND agent.organization_id=root.organization_id\n        AND agent.project_id=root.project_id\n    WHERE gate.id=NEW.owner_rework_gate_id AND gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.root_run_id\n        AND gate.state='CHANGES_REQUESTED' AND gate.decision='REQUEST_CHANGES'\n        AND gate.allowed_decisions @> ARRAY['REQUEST_CHANGES']::text[] AND gate.integration_invocation_id IS NULL\n        AND gate.scope_kind='PROJECT' AND COALESCE(version.spec->>'ExecutionMode','')<>'SERVER_DAG_V1'\n        AND predecessor.workflow_business_attempt=0 AND predecessor.workflow_step_origin_node_id IS NULL\n        AND predecessor.state='SUCCEEDED' AND prior.state='SUCCEEDED'\n        AND EXISTS (SELECT 1 FROM jsonb_array_elements(version.spec->'Steps') step(value)\n            WHERE step.value->>'Key'=logical_origin.workflow_step_key AND step.value->>'AgentRef'=agent.ref\n                AND step.value->>'HumanGateAfter'='true');\n    IF NOT FOUND OR NEW.agent_id<>original.agent_id OR NEW.workflow_step_key<>original.workflow_step_key\n        OR NOT EXISTS (SELECT 1 FROM control_plane.runs physical\n            JOIN control_plane.session_turns turn ON turn.id=NEW.turn_id AND turn.organization_id=NEW.organization_id\n                AND turn.run_id=physical.id AND turn.session_id=physical.session_id\n            WHERE physical.id=NEW.run_id AND physical.organization_id=NEW.organization_id\n                AND physical.root_run_id=original.root_id AND physical.project_id=original.project_id\n                AND physical.workflow_version_id=original.workflow_version_id\n                AND physical.retry_of_run_id=original.run_id AND physical.attempt=original.run_attempt+1\n                AND physical.source='AGENT_DELEGATION' AND physical.initiated_by=original.initiated_by)\n    THEN RAISE EXCEPTION 'legacy rework does not match its stored owner decision' USING ERRCODE='23514'; END IF;\n    IF NEW.owner_rework_origin_node_id IS NOT NULL THEN\n        SELECT * INTO first_node FROM control_plane.run_nodes origin WHERE origin.id=NEW.owner_rework_origin_node_id;\n        IF NOT FOUND OR first_node.id=NEW.id OR first_node.owner_rework_origin_node_id IS NOT NULL\n            OR first_node.owner_rework_gate_id IS DISTINCT FROM NEW.owner_rework_gate_id\n            OR ROW(first_node.organization_id,first_node.root_run_id,first_node.run_id,first_node.agent_id,first_node.workflow_step_key)\n                IS DISTINCT FROM ROW(NEW.organization_id,NEW.root_run_id,NEW.run_id,NEW.agent_id,NEW.workflow_step_key)\n            OR NEW.attempt<=first_node.attempt THEN\n            RAISE EXCEPTION 'legacy technical continuation lost its owner origin' USING ERRCODE='23514';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND $function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"1e54e3fd2baa899d75ea376c80f02076","strict":false,"volatility":"v"},"control_plane.guard_personal_credential_test()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_personal_credential_test()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nBEGIN\n    IF TG_OP='DELETE' THEN\n        RAISE EXCEPTION 'personal credential test history cannot be deleted' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='INSERT' THEN\n        IF NEW.state<>'DUE' OR NEW.generation<>0 OR NEW.version<>1 THEN\n            RAISE EXCEPTION 'personal credential test initial state is invalid' USING ERRCODE='23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF (NEW.id,NEW.ref,NEW.organization_id,NEW.connection_id,NEW.binding_id,NEW.subject_id,NEW.credential_revision_id,NEW.input_schema_version,NEW.input_snapshot,NEW.created_at)\n       IS DISTINCT FROM\n       (OLD.id,OLD.ref,OLD.organization_id,OLD.connection_id,OLD.binding_id,OLD.subject_id,OLD.credential_revision_id,OLD.input_schema_version,OLD.input_snapshot,OLD.created_at) OR\n       OLD.version=9223372036854775807 OR NEW.version<>OLD.version+1 OR NOT (\n        (OLD.state='DUE' AND NEW.state='CLAIMED' AND NEW.generation=1) OR\n        (OLD.state='DUE' AND NEW.state='CANCELLED' AND NEW.generation=0) OR\n        (OLD.state='CLAIMED' AND NEW.state IN ('PROBING','FAILED','CANCELLED') AND NEW.generation=OLD.generation) OR\n        (OLD.state='PROBING' AND NEW.state IN ('SUCCEEDED','FAILED','CANCELLED') AND NEW.generation=OLD.generation)\n       ) OR (OLD.probe_admitted_at IS NOT NULL AND NEW.probe_admitted_at IS DISTINCT FROM OLD.probe_admitted_at) OR\n       (OLD.probe_admitted_at IS NULL AND NEW.probe_admitted_at IS NOT NULL AND NOT (OLD.state='CLAIMED' AND NEW.state='PROBING')) OR\n       (OLD.state='CLAIMED' AND NEW.state='PROBING' AND\n        (NEW.lease_ref,NEW.fence_digest,NEW.workload_instance,NEW.lease_expires_at) IS DISTINCT FROM\n        (OLD.lease_ref,OLD.fence_digest,OLD.workload_instance,OLD.lease_expires_at)) THEN\n        RAISE EXCEPTION 'personal credential test transition is invalid' USING ERRCODE='23514';\n    END IF;\n    NEW.updated_at:=clock_timestamp();\n    RETURN NEW;\nEND;\n$function$\