ission_profile='JIRA_SERVER_ISSUE_CREATE_V1' AND invocation.capability_key='jira.issue.create')\n                OR (NEW.resource_permission_profile='JIRA_SERVER_COMMENT_WRITE_V1' AND invocation.capability_key='jira.issue.comment.write')\n                OR (NEW.resource_permission_profile='JIRA_SERVER_TRANSITION_APPLY_V1' AND invocation.capability_key='jira.issue.transition.apply'))\n              AND invocation.operation=invocation.capability_key\n              AND invocation.risk='WRITE' AND invocation.approval_policy='HUMAN_EACH_EFFECT'\n              AND invocation.resource_kind='JIRA_PROJECT'\n              AND binding.verified_capabilities @> ARRAY['jira.project.read','jira.identity.read']::text[]\n              AND NOT binding.denied_capabilities && ARRAY['jira.project.read','jira.identity.read']::text[])\n            OR (connection.definition_key='gitlab'\n              AND ((NEW.resource_permission_profile='GITLAB_PROJECT_ISSUE_CREATE_V1'\n                  AND invocation.capability_key='gitlab.issue.create' AND invocation.risk='WRITE')\n                OR (NEW.resource_permission_profile='GITLAB_PROJECT_BRANCH_CREATE_V1'\n                  AND invocation.capability_key='gitlab.branch.create' AND invocation.risk='SENSITIVE')\n                OR (NEW.resource_permission_profile='GITLAB_PROJECT_MERGE_REQUEST_CREATE_V1'\n                  AND invocation.capability_key='gitlab.merge_request.create' AND invocation.risk='SENSITIVE'))\n              AND invocation.operation=invocation.capability_key AND invocation.approval_policy='HUMAN_EACH_EFFECT'\n              AND invocation.resource_kind='GITLAB_PROJECT'\n              AND binding.observed_permission_profiles @> ARRAY['GITLAB_PROJECT_WRITE_SCOPE_V1']::text[]\n              AND binding.verified_capabilities @> ARRAY['gitlab.project.metadata.read']::text[]\n              AND NOT binding.denied_capabilities && ARRAY['gitlab.project.metadata.read']::text[])\n            OR (NEW.resource_permission_profile='GITLAB_PROJECT_OBJECT_READ_V1'\n              AND connection.definition_key='gitlab'\n              AND invocation.capability_key IN ('gitlab.repository.file.read','gitlab.issue.read','gitlab.merge_request.read','gitlab.pipeline.read')\n              AND invocation.operation=invocation.capability_key\n              AND invocation.risk='READ' AND invocation.approval_policy='NONE'\n              AND invocation.resource_kind='GITLAB_PROJECT'\n              AND binding.verified_capabilities @> ARRAY['gitlab.project.metadata.read']::text[]\n              AND NOT binding.denied_capabilities && ARRAY['gitlab.project.metadata.read']::text[])\n            OR (NEW.resource_permission_profile='JIRA_SERVER_PROJECT_OBJECT_READ_V1'\n              AND connection.definition_key='jira-server-dc'\n              AND invocation.capability_key IN ('jira.issue.search','jira.issue.read','jira.issue.transition.list')\n              AND invocation.operation=invocation.capability_key\n              AND invocation.risk='READ' AND invocation.approval_policy='NONE'\n              AND invocation.resource_kind='JIRA_PROJECT'\n              AND binding.verified_capabilities @> ARRAY['jira.project.read','jira.identity.read']::text[]\n              AND NOT binding.denied_capabilities && ARRAY['jira.project.read','jira.identity.read']::text[])\n            OR (NEW.resource_permission_profile='CONFLUENCE_SERVER_SPACE_OBJECT_READ_V1'\n              AND connection.definition_key='confluence-server-dc'\n              AND invocation.capability_key IN ('confluence.page.search','confluence.page.read')\n              AND invocation.operation=invocation.capability_key\n              AND invocation.risk='READ' AND invocation.approval_policy='NONE'\n              AND invocation.resource_kind='CONFLUENCE_SPACE'\n              AND binding.verified_capabilities @> ARRAY['confluence.space.read','confluence.identity.read']::text[]\n              AND NOT binding.denied_capabilities && ARRAY['confluence.space.read','confluence.identity.read']::text[])\n          )\n          AND NOT invocation.capability_key=ANY(binding.denied_capabilities)\n    ) THEN\n        RAISE EXCEPTION 'personal invocation credential lineage is invalid' USING ERRCODE='23514';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"5c7136220480805d6142d100b45792ea","strict":false,"volatility":"v"},"control_plane.guard_ssh_compose_admission_block()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_ssh_compose_admission_block()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF OLD.ssh_compose_admission_blocked OR NEW.ssh_compose_admission_blocked THEN\n    IF NEW.ssh_compose_snapshot IS NULL\n       OR NEW.operation NOT IN ('ssh.compose.inspect','ssh.compose.deploy','ssh.compose.status')\n       OR NEW.effect_receipt_id IS NOT NULL\n       OR (OLD.ssh_compose_admission_blocked AND\n          (NOT NEW.ssh_compose_admission_blocked OR\n           NEW.ssh_compose_admission_block_reason IS DISTINCT FROM OLD.ssh_compose_admission_block_reason))\n       OR ROW(NEW.id,NEW.organization_id,NEW.run_id,NEW.node_id,NEW.connection_id,\n              NEW.grant_id,NEW.grant_version,NEW.capability_key,NEW.idempotency_key,NEW.intent_digest,NEW.approval_scope_id,NEW.approval_scope_paths,NEW.mailbox_gate_required,NEW.definition_version,NEW.definition_digest,\n              NEW.operation,NEW.risk,NEW.approval_policy,NEW.resource_kind,NEW.resource_scope,\n              NEW.resource_scope_digest,NEW.effect_key,NEW.input_digest,NEW.bounded_input,\n              NEW.ssh_compose_snapshot,NEW.ssh_compose_deadline,NEW.ssh_compose_recovery,\n              NEW.generation,NEW.claimed_workload,NEW.claimed_lease_ref,NEW.claimed_fence_digest,\n              NEW.effect_receipt_id)\n          IS DISTINCT FROM\n          ROW(OLD.id,OLD.organization_id,OLD.run_id,OLD.node_id,OLD.connection_id,\n              OLD.grant_id,OLD.grant_version,OLD.capability_key,OLD.idempotency_key,OLD.intent_digest,OLD.approval_scope_id,OLD.approval_scope_paths,OLD.mailbox_gate_required,OLD.definition_version,OLD.definition_digest,\n              OLD.operation,OLD.risk,OLD.approval_policy,OLD.resource_kind,OLD.resource_scope,\n              OLD.resource_scope_digest,OLD.effect_key,OLD.input_digest,OLD.bounded_input,\n              OLD.ssh_compose_snapshot,OLD.ssh_compose_deadline,OLD.ssh_compose_recovery,\n              OLD.generation,OLD.claimed_workload,OLD.claimed_lease_ref,OLD.claimed_fence_digest,\n              OLD.effect_receipt_id)\n       OR NEW.lease_ref IS NOT NULL OR NEW.effect_fence_digest IS NOT NULL\n       OR NEW.workload_instance IS NOT NULL OR NEW.lease_expires_at IS NOT NULL\n       OR OLD.state NOT IN ('READY','UNKNOWN_OUTCOME','FAILED','CANCELLED')\n       OR (NOT OLD.ssh_compose_admission_blocked AND NEW.state IS DISTINCT FROM OLD.state)\n       OR (OLD.state='UNKNOWN_OUTCOME' AND\n           ROW(NEW.state,NEW.result_summary,NEW.safe_error_code) IS DISTINCT FROM\n           ROW(OLD.state,OLD.result_summary,OLD.safe_error_code))\n       OR (OLD.state<>'UNKNOWN_OUTCOME' AND NEW.state NOT IN ('READY','FAILED','CANCELLED')) THEN\n      RAISE EXCEPTION 'SSH Compose blocked admission is immutable';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"c504ff89154b91a03cfedd56dc5f9de2","strict":false,"volatility":"v"},"control_plane.guard_ssh_compose_snapshot()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_ssh_compose_snapshot()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nBEGIN\n  IF OLD.ssh_compose_snapshot IS NOT NULL AND OLD.ssh_compose_snapshot IS DISTINCT FROM NEW.ssh_compose_snapshot THEN\n    RAISE EXCEPTION 'SSH Compose snapshot is immutable';\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"eb414956bfcd23b3e22d5093b6882e7d","strict":false,"volatility":"v"},"control_plane.guard_workflow_exception_episodes()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_workflow_exception_episodes()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nDECLARE old_count integer; new_count integer; previous jsonb; episode jsonb; immutable_keys text[];\n        terminal boolean; published jsonb;\nBEGIN\n    IF TG_OP='DELETE' THEN\n        IF OLD.workflow_exception_history<>'[]'::jsonb OR OLD.workflow_exception IS NOT NULL THEN\n            IF NOT control_plane.project_purge_authorized() OR NOT EXISTS (\n                SELECT 1 FROM control_plane.project_purge_targets target\n                JOIN control_plane.project_purge_context context USING (transaction_id)\n                WHERE target.transaction_id=pg_current_xact_id_if_assigned() AND context.backend_pid=pg_backend_pid()\n                    AND target.relation_id='control_plane.runs'::regclass AND target.row_key=jsonb_build_array(OLD.id)\n            ) THEN\n                RAISE EXCEPTION 'workflow exception history requires authorized project purge'\n                    USING ERRCODE='23514', CONSTRAINT='workflow_exception_delete_authority';\n            END IF;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF TG_OP='INSERT' THEN\n        IF NEW.workflow_exception_history<>'[]'::jsonb OR NEW.workflow_exception IS NOT NULL THEN\n            RAISE EXCEPTION 'workflow exception history must start empty' USING ERRCODE='23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n    terminal:=NEW.state IN ('FAILED','CANCELLED');\n    old_count:=jsonb_array_length(OLD.workflow_exception_history);\n    IF terminal AND OLD.workflow_exception IS NOT NULL AND old_count>0 THEN\n        episode:=OLD.workflow_exception_history->-1;\n        IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN\n            episode:=episode||jsonb_build_object('state',CASE WHEN EXISTS (\n                    SELECT 1 FROM control_plane.owner_gates decision_gate\n                    WHERE decision_gate.id::text=episode->>'gateId' AND decision_gate.ref=episode->>'gateRef'\n                        AND decision_gate.organization_id=NEW.organization_id AND decision_gate.root_run_id=NEW.id\n                        AND decision_gate.project_id=NEW.project_id\n                        AND decision_gate.state='REJECTED' AND decision_gate.decision='REJECT'\n                ) THEN 'REJECTED' ELSE 'CANCELLED' END,\n                'version',(episode->>'version')::bigint+1);\n            NEW.workflow_exception_history:=jsonb_set(OLD.workflow_exception_history,ARRAY[(old_count-1)::text],episode);\n            NEW.workflow_exception:=NULL;\n        END IF;\n    END IF;\n    IF NEW.workflow_exception_history IS NOT DISTINCT FROM OLD.workflow_exception_history\n       AND NEW.workflow_exception IS NOT DISTINCT FROM OLD.workflow_exception THEN\n        IF NEW.state='SUCCEEDED' AND NEW.workflow_exception IS NOT NULL THEN\n            RAISE EXCEPTION 'workflow recovery blocks successful root completion' USING ERRCODE='23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF NEW.id IS DISTINCT FROM NEW.root_run_id OR jsonb_typeof(NEW.workflow_exception_history) IS DISTINCT FROM 'array' THEN\n        RAISE EXCEPTION 'workflow episodes belong to one root' USING ERRCODE='23514';\n    END IF;\n    SELECT version.spec INTO published FROM control_plane.workflow_versions version\n    JOIN control_plane.workflows workflow ON workflow.id=version.workflow_id AND workflow.organization_id=version.organization_id\n    WHERE version.id=NEW.workflow_version_id AND version.organization_id=NEW.organization_id\n        AND workflow.project_id=NEW.project_id AND version.spec->>'ExecutionMode'='SERVER_DAG_V1';\n    IF published IS NULL THEN RAISE EXCEPTION 'workflow episode requires pinned server policy' USING ERRCODE='23514'; END IF;\n    new_count:=jsonb_array_length(NEW.workflow_exception_history);\n    IF new_count<1 OR new_count>48 OR new_count<old_count OR new_count>old_count+1 OR EXISTS (\n        SELECT 1 FROM jsonb_array_elements(OLD.workflow_exception_history) WITH ORDINALITY item(value,position)\n        WHERE item.position<=LEAST(old_count,new_count-1) AND NEW.workflow_exception_history->(item.position::integer-1) IS DISTINCT FROM item.value\n    ) THEN RAISE EXCEPTION 'workflow episode prefix is immutable' USING ERRCODE='23514'; END IF;\n    episode:=NEW.workflow_exception_history->-1;\n    IF jsonb_typeof(episode) IS DISTINCT FROM 'object'\n       OR episode-ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state',\n           'managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId','inputs','kind','reworkPlan']<>'{}'::jsonb\n       OR NOT episode ?& ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state','inputs']\n       OR episode->'episode' IS DISTINCT FROM to_jsonb(new_count)\n       OR jsonb_typeof(episode->'inputs') IS DISTINCT FROM 'array'\n       OR jsonb_array_length(episode->'inputs')>8\n       OR jsonb_typeof(episode->'state') IS DISTINCT FROM 'string'\n       OR jsonb_typeof(episode->'attempt') IS DISTINCT FROM 'number'\n       OR jsonb_typeof(episode->'version') IS DISTINCT FROM 'number'\n       OR jsonb_typeof(episode->'reason') IS DISTINCT FROM 'string'\n       OR (episode->>'reason')!~'^[A-Z_]{1,96}$'\n       OR episode->>'state' NOT IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER','RECOVERED','REJECTED','CANCELLED') THEN\n        RAISE EXCEPTION 'workflow episode shape is invalid' USING ERRCODE='23514';\n    END IF;\n    IF (episode ? 'kind') IS DISTINCT FROM (episode ? 'reworkPlan')\n        OR (episode ? 'kind' AND (episode->>'kind'<>'UPSTREAM_REWORK' OR published->>'ReworkPolicy' IS DISTINCT FROM 'OWNER_APPROVED_UPSTREAM_V1')) THEN\n        RAISE EXCEPTION 'workflow rework requires the explicit published profile' USING ERRCODE='23514';\n    END IF;\n    IF new_count=old_count+1 AND episode ? 'kind' AND control_plane.workflow_upstream_plan_valid(NEW.organization_id,NEW.id,episode) IS NOT TRUE THEN\n        RAISE EXCEPTION 'workflow upstream plan differs from exact published subjects' USING ERRCODE='23514';\n    END IF;\n    IF new_count=old_count+1 THEN\n        IF old_count>0 AND (OLD.workflow_exception IS NOT NULL OR OLD.workflow_exception_history->-1->>'state' NOT IN ('RECOVERED','REJECTED','CANCELLED')) THEN\n            RAISE EXCEPTION 'workflow episode already active' USING ERRCODE='23514';\n        END IF;\n        IF episode->'version' IS DISTINCT FROM '1'::jsonb OR episode->>'state'<>'PENDING_MANAGER'\n           OR episode ?| ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']\n           OR (episode->>'attempt')::integer NOT BETWEEN 0 AND 4 OR NOT EXISTS (\n            SELECT 1 FROM control_plane.run_nodes anchor\n            JOIN control_plane.run_nodes physical ON physical.id::text=episode->>'finalNodeId'\n                AND physical.organization_id=anchor.organization_id AND physical.root_run_id=anchor.root_run_id\n            WHERE anchor.organization_id=NEW.organization_id AND anchor.root_run_id=NEW.id\n                AND anchor.id::text=episode->>'originNodeId' AND anchor.workflow_step_origin_node_id IS NULL\n                AND anchor.workflow_step_key=episode->>'stepKey'\n                AND ((episode->>'attempt'='0' AND anchor.id=physical.id AND anchor.workflow_business_attempt=0\n                    AND anchor.state='PLANNED' AND anchor.materialization_state='PLANNED')\n                  OR (episode->>'attempt'<>'0' AND COALESCE(physical.workflow_step_origin_node_id,physical.id)=anchor.id\n                    AND physical.workflow_business_attempt=(episode->>'attempt')::integer\n                    AND physical.workflow_inputs=episode->'inputs'\n                    AND jsonb_array_length(anchor.workflow_attempts)=(episode->>'attempt')::integer\n                    AND anchor.workflow_attempts->-1->'provenance'->>'nodeId'=physical.id::text\n                    AND (anchor.workflow_attempts->-1->>'reason'=episode->>'reason'\n                         OR (episode->>'reason'='OWNER_CHANGES_REQUESTED' AND anchor.workflow_attempts->-1->>'accepted'='true'))))\n        ) THEN RAISE EXCEPTION 'workflow episode requires exact current attempt' USING ERRCODE='23514'; END IF;\n    ELSE\n        previous:=OLD.workflow_exception_history->-1;\n        immutable_keys:=ARRAY['version','state','managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId'];\n        IF episode-immutable_keys IS DISTINCT FROM previous-immutable_keys\n           OR episode->'version' IS DISTINCT FROM to_jsonb((previous->>'version')::bigint+1)\n           OR NOT ((previous->>'state'='PENDING_MANAGER' AND episode->>'state' IN ('MANAGER_QUEUED','WAITING_OWNER'))\n               OR (previous->>'state'='MANAGER_QUEUED' AND episode->>'state'='WAITING_OWNER')\n               OR (previous->>'state'='WAITING_OWNER' AND episode->>'state'='RECOVERED')\n               OR (terminal AND previous->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER')\n                   AND episode->>'state' IN ('REJECTED','CANCELLED')))\n           OR EXISTS (SELECT 1 FROM unnest(ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']) pin\n               WHERE previous ? pin AND episode->pin IS DISTINCT FROM previous->pin) THEN\n            RAISE EXCEPTION 'workflow episode transition or pins changed' USING ERRCODE='23514';\n        END IF;\n    END IF;\n    IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN\n        IF NEW.workflow_exception IS DISTINCT FROM episode OR NEW.state NOT IN ('QUEUED','RUNNING','WAITING_HUMAN') THEN\n            RAISE EXCEPTION 'workflow active episode pin differs' USING ERRCODE='23514';\n        END IF;\n    ELSIF NEW.workflow_exception IS NOT NULL THEN RAISE EXCEPTION 'workflow terminal episode remains active' USING ERRCODE='23514'; END IF;\n    IF episode ? 'managerNodeId' AND NOT EXISTS (\n        SELECT 1 FROM control_plane.run_nodes node\n        JOIN control_plane.agents agent ON agent.id=node.agent_id AND agent.organization_id=node.organization_id AND agent.project_id=NEW.project_id\n        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id\n            AND node.id::text=episode->>'managerNodeId' AND node.ref=episode->>'managerNodeRef'\n            AND node.workflow_step_key='workflow.coordinator.exception.'||(episode->>'episode')\n            AND node.workflow_business_attempt=0 AND agent.ref=published->>'CoordinatorAgentRef'\n    ) THEN RAISE EXCEPTION 'workflow manager pin differs' USING ERRCODE='23514'; END IF;\n    IF episode->>'state'='WAITING_OWNER' AND episode ? 'managerNodeId' AND NOT EXISTS (\n        SELECT 1 FROM control_plane.run_nodes node\n        JOIN control_plane.runtime_revisions revision ON revision.node_id=node.id AND revision.organization_id=node.organization_id\n            AND revision.run_id=node.run_id AND revision.root_run_id=node.root_run_id AND revision.turn_id=node.turn_id\n            AND revision.agent_id=node.agent_id AND revision.attempt=node.attempt\n        JOIN control_plane.runtime_leases lease ON lease.runtime_revision_id=revision.id AND lease.organization_id=revision.organization_id\n            AND lease.run_id=revision.run_id AND lease.node_id=node.id AND lease.generation=revision.generation AND lease.state='COMPLETED'\n        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id AND node.id::text=episode->>'managerNodeId'\n            AND node.state IN ('SUCCEEDED','FAILED')\n    ) THEN RAISE EXCEPTION 'workflow manager is not completed' USING ERRCODE='23514'; END IF;\n    IF episode->>'state'='WAITING_OWNER' AND NOT EXISTS (\n        SELECT 1 FROM control_plane.owner_gates gate\n        JOIN control_plane.run_nodes gate_node ON gate_node.id=gate.node_id AND gate_node.organization_id=gate.organization_id\n        WHERE gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.project_id=NEW.project_id\n            AND gate.id::text=episode->>'gateId' AND gate.ref=episode->>'gateRef' AND gate.state='OPEN'\n            AND gate_node.parent_node_id::text=COALESCE(episode->>'managerNodeId',episode->>'finalNodeId')\n    ) THEN RAISE EXCEPTION 'workflow recovery gate pin differs' USING ERRCODE='23514'; END IF;\n    IF episode->>'state'='RECOVERED' AND NOT EXISTS (\n        SELECT 1 FROM control_plane.run_nodes node\n        JOIN control_plane.owner_gates gate ON gate.id::text=episode->>'gateId'\n            AND gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.state='APPROVED'\n        WHERE node.id::text=episode->>'recoveryNodeId' AND node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id\n            AND ((NOT episode ? 'kind'\n                AND node.workflow_business_attempt=(episode->>'attempt')::integer+1\n                AND COALESCE(node.workflow_step_origin_node_id,node.id)::text=episode->>'originNodeId'\n                AND node.workflow_inputs=episode->'inputs' AND (episode->>'attempt')::integer<4)\n              OR (episode->>'kind'='UPSTREAM_REWORK' AND node.workflow_rework_gate_id=gate.id\n                AND node.workflow_business_attempt BETWEEN 2 AND 4\n                AND COALESCE(episode->'reworkPlan'->>'blockReason','')=''\n                AND EXISTS(SELECT 1 FROM jsonb_array_elements(episode->'reworkPlan'->'targets') member(value)\n                    WHERE member.value->>'originNodeId'=node.workflow_step_origin_node_id::text\n                        AND member.value->>'stepKey'=node.workflow_step_key\n                        AND member.value->'nextAttempt'=to_jsonb(node.workflow_business_attempt))))\n            AND (episode->>'episode')::integer<48\n    ) THEN RAISE EXCEPTION 'workflow fresh recovery execution differs' USING ERRCODE='23514'; END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"464af424a0b0ad947ddb89aa2119c733","strict":false,"volatility":"v"},"control_plane.integration_connection_configuration_ready(uuid)":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":["p_connection_id"],"argumentTypes":"p_connection_id uuid","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.integration_connection_configuration_ready(p_connection_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nSELECT COALESCE((\n    SELECT connection.enabled AND connection.lifecycle_state='ACTIVE'\n      AND definition.enabled AND definition.adapter_readiness='READY'\n      AND (definition.adapter_owner,definition.execution_route) IN\n          (('integration-gateway','MANAGED_MCP'),('interaction-gateway','INTERACTION'))\n      AND CASE connection.credential_policy\n        WHEN 'PROJECT_SHARED' THEN connection.state='CONNECTED' AND (\n          definition.credential_secret_key IS NULL OR (\n            connection.masked_credentials_state='CONFIGURED' AND EXISTS (\n              SELECT 1 FROM control_plane.integration_credential_revisions credential\n              WHERE credential.id=connection.credential_revision_id\n                AND credential.connection_id=connection.id\n                AND credential.organization_id=connection.organization_id\n            )\n          )\n        )\n        WHEN 'INITIATOR_REQUIRED' THEN connection.state IN ('NOT_CONNECTED','CONNECTED')\n          AND definition.adapter_owner='integration-gateway'\n          AND definition.execution_route='MANAGED_MCP'\n        ELSE false\n      END\n    FROM control_plane.integration_connections connection\n    JOIN control_plane.integration_definitions definition ON definition.stable_key=connection.definition_key\n    WHERE connection.id=p_connection_id\n),false);\n$function$\n","kind":"f","language":"sql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"boolean","set":false,"sourceMD5":"573b3d08060a537d8dcfde9ba54cc029","strict":false,"volatility":"s"},"control_plane.integration_grant_admission(uuid,uuid,uuid,text,text,text,text,text,text,text[])":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":["i","i","i","i","i","i","i","i","i","i","t","t","t","t","t","t","t","t","t","t","t","t","t","t","t","t","t"],"argumentNames":["p_tenant","p_actor","p_authority_project","p_connection_ref","p_project_ref","p_recipient_kind","p_recipient_ref","p_capability_key","p_purpose","p_workflow_capabilities","connection_id","connection_ref","connection_version","definition_key","definition_version","definition_digest","project_id","project_ref","project_name","project_version","recipient_kind","recipient_ref","recipient_name","recipient_version","capability_key","capability_name","reason"],"argumentTypes":"p_tenant uuid, p_actor uuid, p_authority_project uuid, p_connection_ref text, p_project_ref text, p_recipient_kind text, p_recipient_ref text, p_capability_key text, p_purpose text, p_workflow_capabilities text[]","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.integration_grant_admission(p_tenant uuid, p_actor uuid, p_authority_project uuid, p_connection_ref text, p_project_ref text, p_recipient_kind text, p_recipient_ref text, p_capability_key text, p_purpose text, p_workflow_capabilities text[])\n RETURNS TABLE(connection_id uuid, connection_ref text, connection_version bigint, definition_key text, definition_version text, definition_digest text, project_id uuid, project_ref text, project_name text, project_version bigint, recipient_kind text, recipient_ref text, recipient_name text, recipient_version bigint, capability_key text, capability_name text, reason text)\n LANGUAGE sql\n STABLE\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nWITH recipients AS (\n    SELECT agent.organization_id, agent.project_id, agent.id, agent.ref,\n           agent.name, agent.version, agent.created_by,\n           'AGENT'::text AS kind,\n           CASE p_purpose WHEN 'GRANT' THEN 'agent.manage' ELSE 'agent.view' END AS permission,\n           agent.enabled AND agent.state='READY' AS ready\n    FROM control_plane.agents agent\n    WHERE agent.organization_id=p_tenant AND agent.state<>'ARCHIVED'\n      AND p_recipient_kind IN ('', 'AGENT')\n      AND (p_recipient_ref='' OR agent.ref=p_recipient_ref)\n    UNION ALL\n    SELECT workflow.organization_id, workflow.project_id, workflow.id, workflow.ref,\n           workflow.name, workflow.version, workflow.created_by,\n           'WORKFLOW', 'workflow.manage', workflow.state IN ('DRAFT','VALID','PUBLISHED')\n    FROM control_plane.workflows workflow\n    WHERE workflow.organization_id=p_tenant AND workflow.state<>'ARCHIVED'\n      AND p_recipient_kind IN ('', 'WORKFLOW') AND p_purpose='GRANT'\n      AND (p_recipient_ref='' OR workflow.ref=p_recipient_ref)\n), connections AS (\n    SELECT connection.*, definition.enabled AS definition_enabled,\n           definition.adapter_readiness, definition.adapter_owner, definition.execution_route,\n           (definition.credential_secret_key IS NULL OR EXISTS (\n               SELECT 1 FROM control_plane.integration_credential_revisions credential\n               WHERE credential.id=connection.credential_revision_id\n                 AND credential.connection_id=connection.id AND credential.organization_id=p_tenant\n                 AND connection.masked_credentials_state='CONFIGURED'\n           )) AS credential_ready,\n           CASE WHEN connection.definition_version=definition.definition_version\n                     AND connection.definition_digest=definition.digest\n                     OR (connection.definition_key='email'\n                         AND connection.definition_version='1.4.0'\n                         AND connection.definition_digest='df52f45643b6e4464cf20901b6c069b88dac671303dc31e04f23b3d1ad4006fd'\n                         AND definition.definition_version='1.4.1'\n                         AND definition.digest='19015eb96a6e5e3edfd8abe9cd885adf8fc82582149dce88421c81dab19424a0')\n                THEN definition.capabilities\n                WHEN connection.definition_key='github'\n                  AND control_plane.integration_github_legacy_capabilities(\n                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest) IS NOT NULL\n                THEN control_plane.integration_github_legacy_capabilities(\n                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest)\n                WHEN connection.definition_key='jira-server-dc'\n                  AND (definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest)\n                    = ('1.1.0','fc35495f83ec21d3698c1e7cfa37eec1075ad35dd30b9dd7f9f680acf989cb31','1.0.0','838878a5a984dafaa8d1c46563e3e660fc3b074515e25376e53ae0cae204fec8')\n                THEN definition.capabilities\n                ELSE (\n                    SELECT revision.content::jsonb #> '{spec,capabilities}'\n                    FROM control_plane.managed_configuration_bindings binding\n                    JOIN control_plane.managed_configuration_sets configuration\n                      ON configuration.id=binding.configuration_set_id\n                     AND configuration.organization_id=binding.organization_id\n                    JOIN control_plane.managed_configuration_revisions revision\n                      ON revision.id=binding.configuration_revision_id\n                     AND revision.organization_id=binding.organization_id\n                     AND revision.configuration_set_id=configuration.id\n                    WHERE binding.organization_id=p_tenant\n                      AND binding.consumer_kind='INTEGRATION_CONNECTION'\n                      AND binding.consumer_ref=connection.ref\n                      AND binding.configuration_kind='INTEGRATION_DEFINITION'\n                      AND configuration.kind='INTEGRATION_DEFINITION'\n                      AND revision.state='PUBLISHED' AND revision.content_format='JSON'\n                      AND encode(public.digest(convert_to(revision.content,'UTF8'),'sha256'),'hex')=connection.definition_digest\n                      AND revision.content::jsonb #>> '{metadata,key}'=connection.definition_key\n                      AND revision.content::jsonb #>> '{metadata,version}'=connection.definition_version\n                ) END AS actual_capabilities\n    FROM control_plane.integration_connections connection\n    JOIN control_plane.integration_definitions definition ON definition.stable_key=connection.definition_key\n    WHERE connection.organization_id=p_tenant AND connection.lifecycle_state='ACTIVE'\n      AND (p_connection_ref='' OR connection.ref=p_connection_ref)\n      AND (control_plane.catalog_resource_visible(p_tenant,p_actor,'integration.manage','INTEGRATION',\n          connection.id,NULL,connection.created_by,'{}'::jsonb,transaction_timestamp())\n        OR (p_purpose='USE' AND control_plane.catalog_resource_visible(p_tenant,p_actor,'integration.view','INTEGRATION',\n          connection.id,NULL,connection.created_by,'{}'::jsonb,transaction_timestamp())))\n)\nSELECT connection.id, connection.ref, connection.version,\n       connection.definition_key, connection.definition_version, connection.definition_digest,\n       project.id, project.ref, project.name, project.version,\n       recipient.kind, recipient.ref, recipient.name, recipient.version,\n       capability.value->>'key', capability.value->>'name',\n       CASE\n         WHEN ((p_purpose='GRANT' OR connection.credential_policy='INITIATOR_REQUIRED') AND NOT control_plane.integration_connection_configuration_ready(connection.id))\n              OR (p_purpose='USE' AND connection.credential_policy='PROJECT_SHARED' AND (NOT connection.enabled OR connection.state<>'CONNECTED' OR NOT connection.credential_ready))\n              OR NOT connection.definition_enabled OR connection.adapter_readiness<>'READY'\n              OR (connection.adapter_owner,connection.execution_route) NOT IN\n                 (('integration-gateway','MANAGED_MCP'),('interaction-gateway','INTERACTION'))\n           THEN 'CONNECTION_UNAVAILABLE'\n         WHEN NOT recipient.ready THEN 'RECIPIENT_UNAVAILABLE'\n         WHEN p_purpose='USE' AND NOT EXISTS (\n           SELECT 1 FROM control_plane.integration_grants grant_row\n           WHERE grant_row.organization_id=p_tenant AND grant_row.connection_id=connection.id\n             AND grant_row.target_kind='AGENT' AND grant_row.target_ref=recipient.ref\n             AND grant_row.capability_key=capability.value->>'key' AND grant_row.enabled\n             AND grant_row.definition_version=connection.definition_version\n             AND grant_row.definition_digest=connection.definition_digest\n         ) THEN 'GRANT_UNAVAILABLE'\n         WHEN p_purpose='USE' AND p_workflow_capabilities IS NOT NULL\n           AND NOT (capability.value->>'key'=ANY(p_workflow_capabilities)) THEN 'WORKFLOW_EXCLUDED'\n         ELSE 'READY'\n       END\nFROM recipients recipient\nJOIN control_plane.projects project ON project.id=recipient.project_id\n AND project.organization_id=p_tenant AND project.lifecycle='ACTIVE'\nCROSS JOIN connections connection\nCROSS JOIN LATERAL jsonb_array_elements(connection.actual_capabilities) capability(value)\nWHERE p_purpose IN ('GRANT','USE')\n  AND (p_project_ref='' OR project.ref=p_project_ref)\n  AND (p_authority_project IS NULL OR project.id=p_authority_project)\n  AND (p_capability_key='' OR capability.value->>'key'=p_capability_key)\n  AND control_plane.catalog_resource_visible(p_tenant,p_actor,recipient.permission,recipient.kind,\n      recipient.id,project.id,recipient.created_by,\n      jsonb_build_object('PROJECT',project.id::text),transaction_timestamp())\n  AND (p_purpose='GRANT' OR (\n      capability.value->>'operation' NOT IN ('mattermost.inbound','mattermost.gate_decisions')\n      AND capability.value->>'risk' IN ('READ','WRITE','SENSITIVE','DESTRUCTIVE')\n      AND control_plane.catalog_resource_visible(p_tenant,p_actor,\n          CASE capability.value->>'risk' WHEN 'READ' THEN 'integration.view' ELSE 'integration.manage' END,\n          'INTEGRATION',connection.id,NULL,connection.created_by,'{}'::jsonb,transaction_timestamp())\n  ));\n$function$\n","kind":"f","language":"sql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"TABLE(connection_id uuid, connection_ref text, connection_version bigint, definition_key text, definition_version text, definition_digest text, project_id uuid, project_ref text, project_name text, project_version bigint, recipient_kind text, recipient_ref text, recipient_name text, recipient_version bigint, capability_key text, capability_name text, reason text)","set":true,"sourceMD5":"daeb4bf82c59d3b70a93cf99c78c6c7e","strict":false,"volatility":"s"},"control_plane.protect_email_mailbox_gate()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":null,"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.protect_email_mailbox_gate()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF TG_OP='UPDATE' AND (NEW.mailbox_gate_required IS DISTINCT FROM OLD.mailbox_gate_required\n        OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy\n        OR NEW.grant_version IS DISTINCT FROM OLD.grant_version\n        OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths) THEN\n        RAISE EXCEPTION 'integration approval binding is immutable';\n    END IF;\n    IF NEW.mailbox_gate_required OR (NEW.risk<>'READ' AND NEW.approval_policy='NONE' AND NEW.resource_kind='EMAIL_SENDER') THEN\n        IF NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c\n                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='email') THEN\n            RAISE EXCEPTION 'mailbox approval requires email owner connection';\n        END IF;\n    ELSIF NEW.risk<>'READ' AND NEW.approval_policy='NONE' THEN\n        IF NEW.risk<>'WRITE' OR NEW.resource_kind<>'GITHUB_REPOSITORY' OR NEW.operation<>NEW.capability_key OR\n           NEW.operation NOT IN ('github.issue.comment.create','github.issue.comment.update','github.pull_request.create','github.pull_request.update','github.pull_request.review.create','github.issue.create','github.issue.update','github.repository.content.create','github.repository.content.update','github.pull_request.comment.create','github.pull_request.comment.update','github.pull_request.ready') OR\n           NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c\n                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='github') OR\n           (NEW.operation='github.pull_request.review.create' AND NEW.bounded_input->>'event' IS DISTINCT FROM 'COMMENT') THEN\n            RAISE EXCEPTION 'autonomous integration write is not allowed';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"398dfe88d74ba308b4d398757bdafdf9","strict":false,"volatility":"v"},"control_plane.protect_workflow_execution_clock()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.protect_workflow_execution_clock()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nDECLARE\n    specification jsonb;\n    step text;\n    seconds integer;\n    started timestamptz;\nBEGIN\n    IF TG_OP='INSERT' THEN\n        IF NEW.execution_started_at IS NOT NULL OR NEW.execution_deadline_at IS NOT NULL\n           OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN\n            RAISE EXCEPTION 'workflow execution clock is assigned on first claim';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF OLD.execution_started_at IS NOT NULL THEN\n        IF ROW(NEW.execution_started_at,NEW.execution_deadline_at,NEW.execution_timeout_seconds,NEW.execution_step_key,NEW.workflow_version_id)\n           IS DISTINCT FROM ROW(OLD.execution_started_at,OLD.execution_deadline_at,OLD.execution_timeout_seconds,OLD.execution_step_key,OLD.workflow_version_id) THEN\n            RAISE EXCEPTION 'workflow execution clock is immutable';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF NEW.execution_started_at IS NULL THEN\n        IF NEW.execution_deadline_at IS NOT NULL OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN\n            RAISE EXCEPTION 'workflow execution clock is incomplete';\n        END IF;\n        RETURN NEW;\n    END IF;\n    SELECT version.spec INTO STRICT specification FROM control_plane.workflow_versions version\n    JOIN control_plane.runs root ON root.workflow_version_id=version.id\n    WHERE root.id=NEW.root_run_id AND root.organization_id=NEW.organization_id\n      AND root.project_id IS NOT DISTINCT FROM NEW.project_id\n      AND NEW.workflow_version_id=version.id;\n    IF NEW.id=NEW.root_run_id THEN\n        step := ''; seconds := (specification->>'TimeoutSeconds')::integer;\n    ELSE\n        SELECT node.workflow_step_key INTO STRICT step FROM control_plane.run_nodes node\n        WHERE node.run_id=NEW.id AND node.organization_id=NEW.organization_id AND node.type='AGENT_EXECUTION';\n        SELECT (item->>'TimeoutSeconds')::integer INTO STRICT seconds\n        FROM jsonb_array_elements(specification->'Steps') item WHERE item->>'Key'=step;\n    END IF;\n    IF seconds<1 OR seconds>(CASE WHEN step='' THEN 604800 ELSE 86400 END)\n       OR NEW.state NOT IN ('QUEUED','RUNNING') THEN\n        RAISE EXCEPTION 'workflow execution clock source is invalid';\n    END IF;\n    started := clock_timestamp();\n    NEW.execution_started_at := started;\n    NEW.execution_timeout_seconds := seconds;\n    NEW.execution_step_key := step;\n    NEW.execution_deadline_at := started+seconds*interval '1 second';\n    RETURN NEW;\nEND $function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"154218ef5ec11c33181a952bd0dcf303","strict":false,"volatility":"v"},"control_plane.purge_project_database(uuid,uuid,text)":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":["p_organization_id","p_project_id","p_objects_digest"],"argumentTypes":"p_organization_id uuid, p_project_id uuid, p_objects_digest text","configuration":["search_path=pg_catalog"],"defaults":0,"definer":true,"definition":"CREATE OR REPLACE FUNCTION control_plane.purge_project_database(p_organization_id uuid, p_project_id uuid, p_objects_digest text)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n    v_transaction_id xid8;\n    v_receipt control_plane.project_purge_receipts%ROWTYPE;\n    v_project_ref text;\n    v_nodes integer;\n    v_node_fingerprint text;\n    v_edges integer;\n    v_edge_fingerprint text;\n    v_edge record;\n    v_table record;\n    v_join text;\n    v_row_key text;\n    v_added integer;\n    v_cycle_added integer;\n    v_deleted_rows integer;\n    v_bad boolean;\nBEGIN\n    SELECT * INTO v_receipt\n    FROM control_plane.project_purge_receipts\n    WHERE organization_id = p_organization_id AND project_id = p_project_id\n    FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'project purge receipt is missing';\n    END IF;\n    IF v_receipt.state = 'DONE' THEN\n        IF v_receipt.objects_digest IS DISTINCT FROM p_objects_digest THEN\n            RAISE EXCEPTION 'project purge receipt digest changed';\n        END IF;\n        RETURN v_receipt.deleted_rows;\n    END IF;\n    IF v_receipt.state <> 'OBJECTS_CLEARED' OR\n       v_receipt.objects_digest IS DISTINCT FROM p_objects_digest OR\n       v_receipt.objects_cleared_at IS NULL THEN\n        RAISE EXCEPTION 'project purge external cleanup is unverified';\n    END IF;\n    SELECT ref INTO v_project_ref FROM control_plane.projects\n    WHERE id = p_project_id AND organization_id = p_organization_id\n      AND lifecycle = 'PURGE_PENDING'\n    FOR UPDATE;\n    IF NOT FOUND OR v_project_ref IS DISTINCT FROM v_receipt.project_ref THEN\n        RAISE EXCEPTION 'project purge target changed';\n    END IF;\n    IF control_plane.project_purge_inventory_digest(p_organization_id, p_project_id)\n       IS DISTINCT FROM p_objects_digest THEN\n        RAISE EXCEPTION 'project purge external inventory changed';\n    END IF;\n\n    WITH RECURSIVE nodes(relation_id) AS (\n        SELECT 'control_plane.projects'::regclass::oid\n        UNION\n        SELECT constraint_row.conrelid FROM nodes\n        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'\n          AND constraint_row.confrelid = nodes.relation_id\n        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace\n          AND namespace_row.nspname = 'control_plane'\n    )\n    SELECT count(*),\n           md5(string_agg(namespace_row.nspname || '.' || class_row.relname,\n                          E'\\n' ORDER BY namespace_row.nspname, class_row.relname))\n    INTO v_nodes, v_node_fingerprint\n    FROM nodes JOIN pg_class class_row ON class_row.oid = nodes.relation_id\n    JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace;\n    IF v_nodes <> 111 OR v_node_fingerprint <> '3eb558fae167872ba6bd17bc68f7a303' THEN\n        RAISE EXCEPTION 'project purge table graph changed';\n    END IF;\n    WITH RECURSIVE nodes(relation_id) AS (\n        SELECT 'control_plane.projects'::regclass::oid\n        UNION\n        SELECT constraint_row.conrelid FROM nodes\n        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'\n          AND constraint_row.confrelid = nodes.relation_id\n        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace\n          AND namespace_row.nspname = 'control_plane'\n    )\n    SELECT count(*), md5(string_agg(\n        child_namespace.nspname || '.' || child_class.relname || '|' ||\n        constraint_row.conname || '|' ||\n        parent_namespace.nspname || '.' || parent_class.relname || '|' ||\n        constraint_row.confdeltype::text,\n        E'\\n' ORDER BY child_namespace.nspname, child_class.relname, constraint_row.conname))\n    INTO v_edges, v_edge_fingerprint\n    FROM pg_constraint constraint_row\n    JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid\n    JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace\n    JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid\n    JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace\n    WHERE constraint_row.contype = 'f'\n      AND constraint_row.confrelid IN (SELECT relation_id FROM nodes)\n      AND constraint_row.conrelid IN (SELECT relation_id FROM nodes);\n    IF v_edges <> 306 OR v_edge_fingerprint <> '19782286a860f9e05cdaad7b6e5f8ef3' THEN\n        RAISE EXCEPTION 'project purge foreign-key graph changed';\n    END IF;\n\n\n    IF EXISTS (\n      WITH RECURSIVE nodes(relation_id) AS (\n        SELECT 'control_plane.projects'::regclass::oid UNION\n        SELECT c.conrelid FROM nodes n JOIN pg_constraint c ON c.confrelid=n.relation_id\n          AND c.contype='f' AND c.connamespace='control_plane'::regnamespace\n      ) SELECT 1 FROM pg_constraint WHERE contype='f' AND confdeltype='a' AND NOT condeferrable\n        AND conrelid IN(SELECT relation_id FROM nodes) AND confrelid IN(SELECT relation_id FROM nodes)\n    ) THEN RAISE EXCEPTION 'project purge deferred foreign-key graph changed'; END IF;\n    v_transaction_id := pg_current_xact_id();\n    INSERT INTO control_plane.project_purge_context(transaction_id, backend_pid, project_id)\n    VALUES (v_transaction_id, pg_backend_pid(), p_project_id);\n\n    PERFORM control_plane.project_purge_recovery_prepare_purge(p_organization_id,p_project_id,p_objects_digest);\n\n    UPDATE control_plane.audit_events event\n    SET assistant_agent_id=NULL\n    FROM control_plane.agents agent\n    WHERE event.organization_id=p_organization_id AND event.assistant_agent_id=agent.id\n      AND agent.organization_id=p_organization_id AND agent.project_id=p_project_id\n      AND event.project_id IS DISTINCT FROM p_project_id;\n\n \n    INSERT INTO control_plane.project_purge_targets(\n        transaction_id, relation_id, row_tid, row_key\n    )\n    SELECT v_transaction_id, project.tableoid::oid, project.ctid,\n           jsonb_build_array(project.id)\n    FROM control_plane.projects project\n    WHERE project.id = p_project_id AND project.organization_id = p_organization_id;\n    SET CONSTRAINTS ALL DEFERRED;\n\n    LOOP\n        v_cycle_added := 0;\n        FOR v_edge IN\n            SELECT constraint_row.conrelid, constraint_row.confrelid,\n                   constraint_row.conkey, constraint_row.confkey,\n                   format('%I.%I', child_namespace.nspname, child_class.relname) AS child_table,\n                   format('%I.%I', parent_namespace.nspname, parent_class.relname) AS parent_table\n            FROM pg_constraint constraint_row\n            JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid\n            JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace\n            JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid\n            JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace\n            WHERE constraint_row.contype = 'f'\n              AND child_namespace.nspname = 'control_plane'\n              AND parent_namespace.nspname = 'control_plane'\n              AND constraint_row.confrelid IN (\n                  SELECT DISTINCT relation_id FROM control_plane.project_purge_targets\n                  WHERE transaction_id = v_transaction_id)\n            ORDER BY constraint_row.conrelid, constraint_row.conname\n        LOOP\n            SELECT string_agg(format('child.%I = parent.%I', child_attribute.attname,\n                                     parent_attribute.attname), ' AND ' ORDER BY child_column.n)\n            INTO v_join\n            FROM unnest(v_edge.conkey) WITH ORDINALITY AS child_column(number, n)\n            JOIN unnest(v_edge.confkey) WITH ORDINALITY AS parent_column(number, n)\n              ON parent_column.n = child_column.n\n            JOIN pg_attribute child_attribute ON child_attribute.attrelid = v_edge.conrelid\n              AND child_attribute.attnum = child_column.number\n            JOIN pg_attribute parent_attribute ON parent_attribute.attrelid = v_edge.confrelid\n              AND parent_attribute.attnum = parent_column.number;\n            IF v_join IS NULL THEN\n                RAISE EXCEPTION 'project purge foreign-key columns changed';\n            END IF;\n            SELECT string_agg(format('child.%I', key_attribute.attname), ', ' ORDER BY key_column.n)\n            INTO v_row_key\n            FROM pg_constraint primary_key\n            CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)\n            JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid\n              AND key_attribute.attnum = key_column.number\n            WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_edge.conrelid;\n            IF v_row_key IS NULL THEN\n                RAISE EXCEPTION 'project purge primary key is missing';\n            END IF;\n            EXECUTE format(\n                'INSERT INTO control_plane.project_purge_targets(transaction_id, relation_id, row_tid, row_key) '\n                'SELECT $1, child.tableoid::oid, child.ctid, jsonb_build_array(%s) FROM %s child '\n                'JOIN %s parent ON %s '\n                'JOIN control_plane.project_purge_targets target ON '\n                'target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = parent.tableoid::oid '\n                'AND target.row_tid = parent.ctid '\n                'FOR UPDATE OF child ON CONFLICT DO NOTHING',\n                v_row_key, v_edge.child_table, v_edge.parent_table, v_join)\n            USING v_transaction_id, v_edge.confrelid;\n            GET DIAGNOSTICS v_added = ROW_COUNT;\n            v_cycle_added := v_cycle_added + v_added;\n        END LOOP;\n        EXIT WHEN v_cycle_added = 0;\n    END LOOP;\n\n    FOR v_table IN\n        SELECT target.relation_id,\n               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name\n        FROM control_plane.project_purge_targets target\n        JOIN pg_class class_row ON class_row.oid = target.relation_id\n        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace\n        WHERE target.transaction_id = v_transaction_id\n        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname\n        ORDER BY target.relation_id\n    LOOP\n        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row\n                   WHERE attribute_row.attrelid = v_table.relation_id\n                     AND attribute_row.attname = 'organization_id' AND NOT attribute_row.attisdropped) THEN\n            EXECUTE format(\n                'SELECT EXISTS (SELECT 1 FROM %s victim '\n                'JOIN control_plane.project_purge_targets target ON '\n                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '\n                'AND target.row_tid = victim.ctid '\n                'WHERE victim.organization_id IS DISTINCT FROM $2)', v_table.table_name)\n            INTO v_bad USING v_transaction_id, p_organization_id, v_table.relation_id;\n            IF v_bad THEN\n                RAISE EXCEPTION 'project purge crossed organization boundary';\n            END IF;\n        END IF;\n        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row\n                   WHERE attribute_row.attrelid = v_table.relation_id\n                     AND attribute_row.attname = 'project_id' AND NOT attribute_row.attisdropped) THEN\n            EXECUTE format(\n                'SELECT EXISTS (SELECT 1 FROM %s victim '\n                'JOIN control_plane.project_purge_targets target ON '\n                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '\n                'AND target.row_tid = victim.ctid '\n                'WHERE victim.project_id IS DISTINCT FROM $2)', v_table.table_name)\n            INTO v_bad USING v_transaction_id, p_project_id, v_table.relation_id;\n            IF v_bad THEN\n                RAISE EXCEPTION 'project purge crossed project boundary';\n            END IF;\n        END IF;\n    END LOOP;\n\n    SELECT count(*) - 1 INTO v_deleted_rows\n    FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;\n    FOR v_table IN\n        SELECT target.relation_id,\n               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name\n        FROM control_plane.project_purge_targets target\n        JOIN pg_class class_row ON class_row.oid = target.relation_id\n        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace\n        WHERE target.transaction_id = v_transaction_id\n          AND target.relation_id <> 'control_plane.projects'::regclass::oid\n        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname\n        ORDER BY target.relation_id\n    LOOP\n        SELECT string_agg(format('victim.%I = (target.row_key->>%s)::%s', key_attribute.attname,\n            key_column.n-1, format_type(key_attribute.atttypid,key_attribute.atttypmod)), ' AND ' ORDER BY key_column.n)\n        INTO v_row_key\n        FROM pg_constraint primary_key\n        CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)\n        JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid\n          AND key_attribute.attnum = key_column.number\n        WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_table.relation_id;\n        IF v_row_key IS NULL THEN\n            RAISE EXCEPTION 'project purge primary key is missing';\n        END IF;\n        EXECUTE format(\n            'DELETE FROM %s victim USING control_plane.project_purge_targets target '\n            'WHERE target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = victim.tableoid::oid '\n            'AND %s', v_table.table_name, v_row_key)\n        USING v_transaction_id, v_table.relation_id;\n    END LOOP;\n    DELETE FROM control_plane.projects\n    WHERE id = p_project_id AND organization_id = p_organization_id;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'project purge target disappeared';\n    END IF;\n    SET CONSTRAINTS ALL IMMEDIATE;\n    UPDATE control_plane.project_purge_receipts\n    SET state = 'DONE', purged_at = statement_timestamp(), deleted_rows = v_deleted_rows\n    WHERE project_id = p_project_id AND organization_id = p_organization_id;\n    DELETE FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;\n    DELETE FROM control_plane.project_purge_context WHERE transaction_id = v_transaction_id;\n    RETURN v_deleted_rows;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"integer","set":false,"sourceMD5":"f3ad2ac00772526202433172f3297c5d","strict":false,"volatility":"v"},"control_plane.reject_integration_immutable_update()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":null,"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.reject_integration_immutable_update()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RAISE EXCEPTION 'immutable integration record cannot be changed';\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"040a2fa74e6953ad26a8985f708905f8","strict":false,"volatility":"v"},"control_plane.revoke_integration_approval_scopes()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentModes":null,"argumentNames":null,"argumentTypes":"","configuration":null,"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.revoke_integration_approval_scopes()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF TG_TABLE_NAME = 'integration_grants' THEN\n        IF NEW.enabled IS DISTINCT FROM OLD.enabled OR NEW.version IS DISTINCT FROM OLD.version\n           OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy\n           OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths\n           OR NEW.definition_version IS DISTINCT FROM OLD.definition_version\n           OR NEW.definition_digest IS DISTINCT FROM OLD.definition_digest\n           OR NEW.resource_scope_digest IS DISTINCT FROM OLD.resource_scope_digest THEN\n            UPDATE control_plane.integration_approval_scopes\n            SET revoked_at=clock_timestamp() WHERE grant_id=OLD.id AND revoked_at IS NULL;\n        END IF;\n    ELSIF TG_TABLE_NAME = 'integration_connections' THEN\n        IF NEW.enabled IS DISTINCT FROM OLD.enabled OR NEW.state IS DISTINCT FROM OLD.state\n           OR NEW.definition_version IS DISTINCT FROM OLD.definition_version\n           OR NEW.definition_digest IS DISTINCT FROM OLD.definition_digest THEN\n            UPDATE control_plane.integration_approval_scopes\n            SET revoked_at=clock_timestamp() WHERE connection_id=OLD.id AND revoked_at IS NULL;\n        END IF;\n    ELSIF TG_TABLE_NAME = 'integration_definitions' THEN\n        IF NEW.enabled IS DISTINCT FROM OLD.enabled OR NEW.digest IS DISTINCT FROM OLD.digest\n           OR NEW.definition_version IS DISTINCT FROM OLD.definition_version\n           OR NEW.adapter_readiness IS DISTINCT FROM OLD.adapter_readiness THEN\n            UPDATE control_plane.integration_approval_scopes scope\n            SET revoked_at=clock_timestamp()\n            WHERE scope.connection_id IN (\n                SELECT connection.id FROM control_plane.integration_connections connection\n                WHERE connection.definition_key=OLD.stable_key\n            ) AND scope.revoked_at IS NULL;\n        END IF;\n    ELSIF TG_TABLE_NAME = 'runs' THEN\n        IF NEW.state IN ('CANCELLING','SUCCEEDED','FAILED','CANCELLED') AND NEW.state IS DISTINCT FROM OLD.state THEN\n            UPDATE control_plane.integration_approval_scopes\n            SET revoked_at=clock_timestamp() WHERE root_run_id=OLD.id AND revoked_at IS NULL;\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"sourceMD5":"9073a1b0d28e1a1c869367cf8f253960","strict":false,"volatility":"v"}},"purgeGraph":{"edgeCount":306,"edgeFingerprint":"19782286a860f9e05cdaad7b6e5f8ef3","edges":[["control_plane.access_bindings","access_bindings_project_id_fkey","