onal_credentials.personal_integration_credential_lifecycle":["CREATE TRIGGER personal_integration_credential_lifecycle BEFORE INSERT OR DELETE OR UPDATE ON control_plane.integration_personal_credentials FOR EACH ROW EXECUTE FUNCTION control_plane.guard_personal_integration_credential()",31,"O",false,false,false,""],"integration_personal_invocation_admissions.personal_invocation_admission_immutable":["CREATE TRIGGER personal_invocation_admission_immutable BEFORE DELETE OR UPDATE ON control_plane.integration_personal_invocation_admissions FOR EACH ROW WHEN ((NOT control_plane.project_purge_authorized())) EXECUTE FUNCTION control_plane.reject_integration_immutable_update()",27,"O",false,false,false,""],"integration_personal_invocation_admissions.personal_invocation_admission_owner":["CREATE TRIGGER personal_invocation_admission_owner BEFORE INSERT ON control_plane.integration_personal_invocation_admissions FOR EACH ROW EXECUTE FUNCTION control_plane.guard_personal_invocation_admission()",7,"O",false,false,false,""],"integration_personal_invocation_credentials.personal_invocation_credential_immutable":["CREATE TRIGGER personal_invocation_credential_immutable BEFORE DELETE OR UPDATE ON control_plane.integration_personal_invocation_credentials FOR EACH ROW WHEN ((NOT control_plane.project_purge_authorized())) EXECUTE FUNCTION control_plane.reject_integration_immutable_update()",27,"O",false,false,false,""],"integration_personal_invocation_credentials.personal_invocation_credential_owner":["CREATE TRIGGER personal_invocation_credential_owner BEFORE INSERT ON control_plane.integration_personal_invocation_credentials FOR EACH ROW EXECUTE FUNCTION control_plane.guard_personal_invocation_credential()",7,"O",false,false,false,""],"runs.integration_approval_scopes_revoke_run":["CREATE TRIGGER integration_approval_scopes_revoke_run AFTER UPDATE OF state ON control_plane.runs FOR EACH ROW EXECUTE FUNCTION control_plane.revoke_integration_approval_scopes()",17,"O",false,false,false,""],"runs.legacy_workflow_rework_run_guard":["CREATE TRIGGER legacy_workflow_rework_run_guard BEFORE DELETE OR UPDATE ON control_plane.runs FOR EACH ROW EXECUTE FUNCTION control_plane.guard_legacy_workflow_rework()",27,"O",false,false,false,""],"runs.workflow_exception_episodes_guard":["CREATE TRIGGER workflow_exception_episodes_guard BEFORE INSERT OR DELETE OR UPDATE ON control_plane.runs FOR EACH ROW EXECUTE FUNCTION control_plane.guard_workflow_exception_episodes()",31,"O",false,false,false,""],"runs.workflow_execution_clock_guard":["CREATE TRIGGER workflow_execution_clock_guard BEFORE INSERT OR UPDATE ON control_plane.runs FOR EACH ROW EXECUTE FUNCTION control_plane.protect_workflow_execution_clock()",23,"O",false,false,false,""],"runs.workspace_volume_root_closed":["CREATE TRIGGER workspace_volume_root_closed AFTER UPDATE OF state ON control_plane.runs FOR EACH ROW WHEN (((old.state IS DISTINCT FROM new.state) AND (new.state = ANY (ARRAY['SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text])))) EXECUTE FUNCTION control_plane.close_workspace_volume_origin()",17,"O",false,false,false,""]}}$expected_personal$::jsonb THEN
