SET LOCAL search_path=pg_catalog;
DO $oidc_identity_catalog$
DECLARE v_actual jsonb;
BEGIN
-- name: platform_oidc_identity_catalog :one
-- Только schema metadata; business rows, LOGIN names и credentials не читаются.
WITH relations AS (
  SELECT c.*, n.nspname FROM pg_catalog.pg_class c
  JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='control_plane' AND c.relname IN
    ('oidc_identity_policies','oidc_identity_policy_current','oidc_identity_sessions','oidc_identity_observations')
), functions AS (
  SELECT p.* FROM pg_catalog.pg_proc p
  WHERE p.pronamespace='control_plane'::regnamespace AND p.proname LIKE 'guard_oidc_identity_%'
), table_catalog AS (
  SELECT r.relname, jsonb_build_object(
    'kind', r.relkind, 'persistence', r.relpersistence, 'owner', pg_get_userbyid(r.relowner),
    'rls',r.relrowsecurity,'forceRls',r.relforcerowsecurity,
    'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,
      a.atthasdef,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated,a.attacl::text) ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
      WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
    'constraints',(SELECT jsonb_object_agg(c.conname,jsonb_build_array(c.contype,c.convalidated,c.conenforced,c.condeferrable,
      c.condeferred,pg_get_constraintdef(c.oid))) FROM pg_catalog.pg_constraint c WHERE c.conrelid=r.oid),
    'indexes',(SELECT jsonb_object_agg(i.indexrelid::regclass::text,jsonb_build_array(i.indisunique,i.indisvalid,
      i.indisready,i.indislive,pg_get_indexdef(i.indexrelid))) FROM pg_catalog.pg_index i WHERE i.indrelid=r.oid),
    'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type)
      FROM aclexplode(coalesce(r.relacl,acldefault('r',r.relowner))) a)
  ) AS metadata FROM relations r
), function_catalog AS (
  SELECT p.oid::regprocedure::text AS name,jsonb_build_object(
    'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
    'definer',p.prosecdef,'kind',p.prokind,'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,
    'leakproof',p.proleakproof,'set',p.proretset,'result',format_type(p.prorettype,NULL),
    'argumentNames',p.proargnames,'defaults',p.pronargdefaults,'configuration',p.proconfig,
    'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type)
      FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)
  ) AS metadata FROM functions p JOIN pg_catalog.pg_language l ON l.oid=p.prolang
), trigger_catalog AS (
  SELECT r.relname||'.'||t.tgname AS name,jsonb_build_array(pg_get_triggerdef(t.oid),t.tgtype,t.tgenabled,
    t.tgdeferrable,t.tginitdeferred,t.tgconstraint<>0,encode(t.tgargs,'hex')) AS metadata
  FROM relations r JOIN pg_catalog.pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal
), sequence_catalog AS (
  SELECT jsonb_build_object('start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,
    'cycle',s.seqcycle,'type',format_type(s.seqtypid,NULL),'owner',pg_get_userbyid(c.relowner),
    'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),a.privilege_type)
      FROM aclexplode(coalesce(c.relacl,acldefault('s',c.relowner))) a)) AS metadata
  FROM pg_catalog.pg_sequence s JOIN pg_catalog.pg_class c ON c.oid=s.seqrelid
  WHERE s.seqrelid='control_plane.oidc_identity_session_revisions'::regclass
)
SELECT jsonb_build_object(
 'tables',(SELECT jsonb_object_agg(relname,metadata) FROM table_catalog),
 'functions',(SELECT jsonb_object_agg(name,metadata) FROM function_catalog),
 'triggers',(SELECT jsonb_object_agg(name,metadata) FROM trigger_catalog),
 'sequence',(SELECT metadata FROM sequence_catalog),
 'subjectOwnerKey',(SELECT jsonb_build_array(contype,convalidated,conenforced,pg_get_constraintdef(oid))
   FROM pg_catalog.pg_constraint WHERE conrelid='control_plane.subjects'::regclass AND conname='subjects_oidc_owner_key')
) INTO v_actual;
IF v_actual IS DISTINCT FROM $expected_oidc${"functions":{"control_plane.guard_oidc_identity_observation()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentNames":null,"configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_oidc_identity_observation()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION 'OIDC identity high-watermark cannot be deleted' USING ERRCODE = '23514';\n    END IF;\n    IF (NEW.organization_id, NEW.subject_id) IS DISTINCT FROM (OLD.organization_id, OLD.subject_id)\n       OR NEW.last_issued_at < OLD.last_issued_at OR NEW.session_revision < OLD.session_revision\n       OR (NEW.last_issued_at = OLD.last_issued_at AND NEW.groups_digest <> OLD.groups_digest) THEN\n        RAISE EXCEPTION 'OIDC identity observation cannot move backwards' USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"strict":false,"volatility":"v"},"control_plane.guard_oidc_identity_policy()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentNames":null,"configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_oidc_identity_policy()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nBEGIN\n    IF TG_TABLE_NAME = 'oidc_identity_policy_current' AND TG_OP = 'UPDATE' THEN\n        IF NEW.singleton IS DISTINCT FROM OLD.singleton OR NEW.revision <= OLD.revision THEN\n            RAISE EXCEPTION 'OIDC policy revision must advance' USING ERRCODE = '23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n    RAISE EXCEPTION 'OIDC policy history cannot be rewritten' USING ERRCODE = '23514';\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"strict":false,"volatility":"v"},"control_plane.guard_oidc_identity_session()":{"acl":[["control_plane_owner","control_plane_owner","EXECUTE",false],["control_plane_runtime","control_plane_owner","EXECUTE",false],["PUBLIC","control_plane_owner","EXECUTE",false]],"argumentNames":null,"configuration":["search_path=pg_catalog, control_plane"],"defaults":0,"definer":false,"definition":"CREATE OR REPLACE FUNCTION control_plane.guard_oidc_identity_session()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'control_plane'\nAS $function$\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION 'OIDC session tombstone cannot be deleted' USING ERRCODE = '23514';\n    END IF;\n    IF (NEW.revision, NEW.organization_id, NEW.subject_id, NEW.issuer,\n        NEW.external_subject, NEW.provider_session_id, NEW.authenticated_at,\n        NEW.absolute_expires_at, NEW.policy_revision, NEW.policy_digest, NEW.created_at)\n       IS DISTINCT FROM\n       (OLD.revision, OLD.organization_id, OLD.subject_id, OLD.issuer,\n        OLD.external_subject, OLD.provider_session_id, OLD.authenticated_at,\n        OLD.absolute_expires_at, OLD.policy_revision, OLD.policy_digest, OLD.created_at)\n       OR NEW.last_issued_at < OLD.last_issued_at\n       OR (OLD.state = 'REVOKED' AND (NEW.state <> 'REVOKED' OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)) THEN\n        RAISE EXCEPTION 'OIDC session transition is invalid' USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"control_plane_owner","parallel":"u","result":"trigger","set":false,"strict":false,"volatility":"v"}},"sequence":{"acl":[["control_plane_owner","control_plane_owner","SELECT",false],["control_plane_owner","control_plane_owner","UPDATE",false],["control_plane_owner","control_plane_owner","USAGE",false],["control_plane_runtime","control_plane_owner","SELECT",false],["control_plane_runtime","control_plane_owner","USAGE",false]],"cache":1,"cycle":false,"increment":1,"max":9007199254740991,"min":1,"owner":"control_plane_owner","start":1,"type":"bigint"},"subjectOwnerKey":["u",true,true,"UNIQUE (organization_id, id)"],"tables":{"oidc_identity_observations":{"acl":[["control_plane_owner","control_plane_owner","DELETE",false],["control_plane_owner","control_plane_owner","INSERT",false],["control_plane_owner","control_plane_owner","MAINTAIN",false],["control_plane_owner","control_plane_owner","REFERENCES",false],["control_plane_owner","control_plane_owner","SELECT",false],["control_plane_owner","control_plane_owner","TRIGGER",false],["control_plane_owner","control_plane_owner","TRUNCATE",false],["control_plane_owner","control_plane_owner","UPDATE",false],["control_plane_runtime","control_plane_owner","INSERT",false],["control_plane_runtime","control_plane_owner","SELECT",false],["control_plane_runtime","control_plane_owner","UPDATE",false],["kodex_backup_reader","control_plane_owner","SELECT",false]],"columns":[["organization_id","uuid",true,false,null,"","",null],["subject_id","uuid",true,false,null,"","",null],["last_issued_at","timestamp with time zone",true,false,null,"","",null],["groups_digest","text",true,false,null,"","",null],["session_revision","bigint",true,false,null,"","",null],["observed_at","timestamp with time zone",true,true,"clock_timestamp()","","",null]],"constraints":{"oidc_identity_observations_groups_digest_check":["c",true,true,false,false,"CHECK ((groups_digest ~ '^[a-f0-9]{64}$'::text))"],"oidc_identity_observations_groups_digest_not_null":["n",true,true,false,false,"NOT NULL groups_digest"],"oidc_identity_observations_last_issued_at_not_null":["n",true,true,false,false,"NOT NULL last_issued_at"],"oidc_identity_observations_observed_at_not_null":["n",true,true,false,false,"NOT NULL observed_at"],"oidc_identity_observations_organization_id_not_null":["n",true,true,false,false,"NOT NULL organization_id"],"oidc_identity_observations_organization_id_subject_id_fkey":["f",true,true,false,false,"FOREIGN KEY (organization_id, subject_id) REFERENCES control_plane.subjects(organization_id, id)"],"oidc_identity_observations_pkey":["p",true,true,false,false,"PRIMARY KEY (organization_id, subject_id)"],"oidc_identity_observations_session_revision_check":["c",true,true,false,false,"CHECK (((session_revision >= 1) AND (session_revision <= '9007199254740991'::bigint)))"],"oidc_identity_observations_session_revision_not_null":["n",true,true,false,false,"NOT NULL session_revision"],"oidc_identity_observations_subject_id_not_null":["n",true,true,false,false,"NOT NULL subject_id"]},"forceRls":false,"indexes":{"control_plane.oidc_identity_observations_pkey":[true,true,true,true,"CREATE UNIQUE INDEX oidc_identity_observations_pkey ON control_plane.oidc_identity_observations USING btree (organization_id, subject_id)"]},"kind":"r","owner":"control_plane_owner","persistence":"p","rls":false},"oidc_identity_policies":{"acl":[["control_plane_owner","control_plane_owner","DELETE",false],["control_plane_owner","control_plane_owner","INSERT",false],["control_plane_owner","control_plane_owner","MAINTAIN",false],["control_plane_owner","control_plane_owner","REFERENCES",false],["control_plane_owner","control_plane_owner","SELECT",false],["control_plane_owner","control_plane_owner","TRIGGER",false],["control_plane_owner","control_plane_owner","TRUNCATE",false],["control_plane_owner","control_plane_owner","UPDATE",false],["control_plane_runtime","control_plane_owner","INSERT",false],["control_plane_runtime","control_plane_owner","SELECT"